/**
 * Real brand logos for the well-known treasury tokens, embedded as base64 PNG
 * data URIs (source: Trust Wallet assets, fetched by contract address) so the
 * treasury composition renders correct token icons offline with no network or
 * Alchemy metadata. Clanker / long-tail tokens fall back to their subgraph
 * `tokenImage`, then to a lettered badge in the component.
 *
 * This file is generated data; the base64 strings are intentionally long.
 */

/* eslint-disable */
/* prettier-ignore */
export const TOKEN_LOGOS: Record<string, string> = {
  ETH: 'data:image/png;base64,',
  WETH: 'data:image/png;base64,',
  USDC: 'data:image/png;base64,',
  USDT: 'data:image/png;base64,',
  DAI: 'data:image/png;base64,',
  HIGHER: 'data:image/png;base64,',
}

/** Local logo data-URI for a known token symbol, or undefined. */
export const tokenLogo = (symbol: string): string | undefined =>
  TOKEN_LOGOS[symbol.toUpperCase()]
